using System;\nusing System.Collections.Concurrent;\nusing System.Collections.Generic;\nusing System.Security.Cryptography;\nusing System.Text;\nusing System.Threading;\nusing System.Threading.Tasks;\n\nnamespace MagnumOpus.Core\n{\n    public enum TxStatus { Pending, Confirmed, Failed }\n\n    public class Transaction\n    {\n        public string From { get; set; }\n        public string To { get; set; }\n        public decimal Amount { get; set; }\n        public string Token { get; set; } = "ETH";\n        public string Nonce { get; set; }\n        public string Signature { get; set; }\n        public TxStatus Status { get; set; } = TxStatus.Pending;\n        public DateTime Timestamp { get; set; } = DateTime.UtcNow;\n        public string Hash { get; set; }\n    }\n\n    public static class CryptoUtils\n    {\n        // Simple mock ECDSA verification using SHA256 hash comparison\n        public static bool VerifySignature(string message, string signature, string publicKey)\n        {\n            // In a real implementation you would use ECDSA. Here we just hash and compare.\n            using var sha = SHA256.Create();\n            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(message + publicKey));\n            var expected = Convert.ToBase64String(hash);\n            return expected == signature;\n        }\n\n        public static string ComputeTxHash(Transaction tx)\n        {\n            var payload = $"{tx.From}|{tx.To}|{tx.Amount}|{tx.Token}|{tx.Nonce}|{tx.Timestamp:o}";\n            using var sha = SHA256.Create();\n            var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(payload));\n            return \"0x\" + BitConverter.ToString(hash).Replace(\"-\", \"\").ToLowerInvariant();\n        }\n    }\n\n    public class TransactionProcessor : IDisposable\n    {\n        private readonly ConcurrentQueue<Transaction> _queue = new();\n        private readonly CancellationTokenSource _cts = new();\n        private readonly Task _worker;\n        private readonly TimeSpan _processingDelay = TimeSpan.FromMilliseconds(200);\n\n        public event Action<Transaction>? OnTransactionProcessed;\n\n        public TransactionProcessor()\n        {\n            _worker = Task.Run(ProcessLoopAsync);\n        }\n\n        public bool Enqueue(Transaction tx)\n        {\n            if (string.IsNullOrWhiteSpace(tx.From) ||\n                string.IsNullOrWhiteSpace(tx.To) ||\n                tx.Amount <= 0 ||\n                string.IsNullOrWhiteSpace(tx.Nonce) ||\n                string.IsNullOrWhiteSpace(tx.Signature))\n            {\n                return false;\n            }\n\n            // Compute hash early for idempotency\n            tx.Hash = CryptoUtils.ComputeTxHash(tx);\n            _queue.Enqueue(tx);\n            return true;\n        }\n\n        private async Task ProcessLoopAsync()\n        {\n            while (!_cts.IsCancellationRequested)\n            {\n                if (_queue.TryDequeue(out var tx))\n                {\n                    await ProcessTransactionAsync(tx);\n                }\n                else\n                {\n                    await Task.Delay(_processingDelay, _cts.Token).ConfigureAwait(false);\n                }\n            }\n        }\n\n        private async Task ProcessTransactionAsync(Transaction tx)\n        {\n            // Simulate network / verification latency\n            await Task.Delay(_processingDelay, _cts.Token).ConfigureAwait(false);\n\n            // Mock verification\n            var message = $"{tx.From}{tx.To}{tx.Amount}{tx.Token}{tx.Nonce}{tx.Timestamp:o}";\n            var isValid = CryptoUtils.VerifySignature(message, tx.Signature, tx.From);\n\n            tx.Status = isValid ? TxStatus.Confirmed : TxStatus.Failed;\n            OnTransactionProcessed?.Invoke(tx);\n        }\n\n        public IEnumerable<Transaction> GetPendingTransactions()\n        {\n            return _queue.ToArray();\n        }\n\n        public void Dispose()\n        {\n            _cts.Cancel();\n            _worker.Wait();\n            _cts.Dispose();\n        }\n    }\n}\n